def policy(obs, P):
    x = obs[0]
    v = obs[1]
    if x <= P["pos_noop_low"]:
        return 1
    if x >= P["pos_noop_high"]:
        return 1
    if v <= P["vel_neg_low"]:
        return 2
    if v <= P["vel_neg_high"]:
        if x <= P["pos_mid"]:
            return 0
        return 2
    if v <= P["vel_pos_thresh"]:
        return 0
    return 2
